-- Specialised MCQ items of varied formats (single / multi-answer / ordering / numeric) for gas-pipeline, PRS/CGS, CP, metering and compressor-station work.
-- Added 2026-10-15; approved by owner instruction (no manual review). ORDER options are stored in the correct sequence (the test shuffles them).
insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref, approval_status, active)
select r.job_role, 'TECHNICAL', v.topic, v.difficulty, v.stem_fa, v.options, v.correct_option, v.item_type, v.answer_key, v.explanation_fa, v.standard_ref, 'APPROVED', true
from (values
  (array['welding_inspector','welding_supervisor'], 'بازرسی چشمی جوش', 2, 'کدام دو مورد از عیوب زیر با بازرسی چشمی سطح سرجوش قابل تشخیص است؟', '["بریدگی کناره (Undercut) در پنجهٔ جوش","سرباره محبوس‌شده بین پاس‌ها در عمق اتصال","تقویت بیش‌ازحد (Excess reinforcement) گردهٔ جوش","نبود ذوب بین پاس‌ها در داخل ضخامت جوش"]'::jsonb, 0, 'MULTI', '[0,2]'::jsonb, 'بریدگی و تقویت اضافی روی سطح قرار دارند؛ سرباره بین پاسی و نبود ذوب داخلی فقط با NDT حجمی (RT/UT) آشکار می‌شوند.', 'API 1104'),
  (array['welding_inspector','welding_supervisor'], 'ترک هیدروژنی', 3, 'کدام دو عامل ریسک ترک سرد هیدروژنی در جوش فولاد خط لوله را بالا می‌برند؟', '["رطوبت الکترود و هیدروژن نفوذی بالا در فلز جوش","ساختار سخت ناشی از CE بالا همراه با سرد شدن سریع","پیش‌گرم کافی و کنترل دمای بین پاسی طبق WPS","پس‌گرم هیدروژن‌زدایی بلافاصله پس از پایان جوش"]'::jsonb, 0, 'MULTI', '[0,1]'::jsonb, 'ترک سرد با سه عامل هم‌زمان رخ می‌دهد: هیدروژن، ساختار سخت و تنش؛ پیش‌گرم و پس‌گرم این ریسک را کم می‌کنند.', 'API 1104 / AWS D1.1 – Hydrogen cracking'),
  (array['welding_inspector','welding_supervisor'], 'تعمیر جوش', 3, 'کدام دو مورد از الزامات تعمیر عیب سرجوش طبق API 1104 درست است؟', '["تعمیر با روش دلخواه جوشکار و بدون روش مدون انجام شود","ترک سطحی با پاس پوششی نهایی بدون برداشتن عیب پوشانده شود","عیب کامل برداشته شود و ناحیه پیش از جوشکاری مجدد بازرسی گردد","ترک‌های بیش از حد مجاز طول با برش کامل سرجوش (Cut-out) رفع شود"]'::jsonb, 0, 'MULTI', '[2,3]'::jsonb, 'تعمیر باید با روش مدون و جوشکار واجد صلاحیت انجام شود، عیب کاملاً برداشته شود و پس از تعمیر دوباره NDT شود؛ ترک‌های بزرگ‌تر از حد مجاز تعمیرپذیر نیستند.', 'API 1104'),
  (array['welding_inspector','welding_supervisor'], 'تعمیر جوش', 2, 'مراحل تعمیر عیب «عدم ذوب» در یک سرجوش را به ترتیب درست مرتب کنید.', '["تعیین دقیق محدودهٔ عیب با NDT و علامت‌گذاری روی سرجوش","برداشت عیب با سنگ‌زنی و تأیید حذف کامل با MT یا بازرسی چشمی","جوشکاری تعمیر با روش مدون و پیش‌گرم لازم","NDT مجدد کل ناحیهٔ تعمیرشده و ثبت نتیجه در گزارش"]'::jsonb, 0, 'ORDER', '[0,1,2,3]'::jsonb, 'عیب باید اول محل‌یابی، بعد کامل برداشته و تأیید شود، سپس جوش تعمیر انجام و دوباره کنترل شود.', 'API 1104'),
  (array['radiography_interpreter'], 'تفسیر فیلم', 2, 'کدام دو عیب در فیلم رادیوگرافی به‌صورت خط تیرهٔ باریک و کشیده دیده می‌شوند؟', '["تخلخل گازی پراکنده (Porosity) در بدنهٔ جوش","عدم نفوذ ریشه (IP) در امتداد مرکز جوش","ادخال تنگستن (Tungsten inclusion) در پاس ریشه","ترک طولی با مسیر نامنظم و نوک‌تیز"]'::jsonb, 0, 'MULTI', '[1,3]'::jsonb, 'IP و ترک خطوط تیرهٔ ممتد هستند؛ تخلخل لکه‌های گرد تیره و ادخال تنگستن لکهٔ روشن (چگالی بالاتر) ایجاد می‌کند.', 'ISO 17636-1 / ASNT RT Handbook'),
  (array['radiography_interpreter'], 'گزارش تفسیر', 2, 'کدام دو مورد باید حتماً در گزارش تفسیر فیلم ثبت شود؟', '["هزینهٔ تعمیر پیشنهادی پیمانکار برای هر سرجوش","شناسهٔ سرجوش و فیلم همراه با موقعیت عیب در محیط لوله","نتیجهٔ پذیرش یا رد بر اساس معیار کد و نوع عیب","برند الکترود مصرفی در پاس پوششی سرجوش"]'::jsonb, 0, 'MULTI', '[1,2]'::jsonb, 'گزارش باید شناسایی سرجوش، نوع و موقعیت عیب، معیار پذیرش و تصمیم نهایی را مستند کند.', 'ISO 17636-1 / API 1104'),
  (array['radiography_interpreter'], 'تفسیر فیلم', 2, 'مراحل تفسیر یک فیلم رادیوگرافی را به ترتیب درست مرتب کنید.', '["بررسی کیفیت فیلم: دانسیته، حساسیت IQI و نبود آرتیفکت","شناسایی ناهمگنی‌ها و تعیین نوع هر عیب","اندازه‌گیری ابعاد عیب و مقایسه با جدول پذیرش","ثبت نتیجهٔ پذیرش یا رد در گزارش رسمی"]'::jsonb, 0, 'ORDER', '[0,1,2,3]'::jsonb, 'فیلم نامناسب اجازهٔ تفسیر نمی‌دهد؛ پس ابتدا کیفیت، سپس تشخیص، اندازه‌گیری و در پایان ثبت.', 'ISO 17636-1'),
  (array['civil_supervisor','civil_engineer'], 'کنترل بتن تازه', 2, 'کدام دو آزمون روی بتن تازه در محل پروژه انجام می‌شود؟', '["اسلامپ (Slump) طبق ASTM C143","مقاومت فشاری ۲۸ روزهٔ نمونه‌ها","مغزه‌گیری از بتن سخت‌شده","دمای بتن هنگام تحویل"]'::jsonb, 0, 'MULTI', '[0,3]'::jsonb, 'اسلامپ و دما روی بتن تازه سنجیده می‌شوند؛ مقاومت ۲۸ روزه و مغزه‌گیری مربوط به بتن سخت‌شده‌اند.', 'ACI 318 / ASTM C143, C1064'),
  (array['civil_supervisor','civil_engineer'], 'طبقه‌بندی خاک', 2, 'کدام دو نوع خاک طبق سیستم USCS «ریزدانه» محسوب می‌شوند؟', '["CL (رس کم‌خمیری)","SW (ماسهٔ خوب دانه‌بندی‌شده)","MH (لای پرخمیری)","GP (شن بد دانه‌بندی‌شده)"]'::jsonb, 0, 'MULTI', '[0,2]'::jsonb, 'در USCS حروف M و C خاک ریزدانه (لای و رس) و G و S خاک درشت‌دانه (شن و ماسه) را نشان می‌دهند.', 'ASTM D2487'),
  (array['civil_supervisor','civil_engineer'], 'تراکم خاک', 2, 'مراحل کنترل تراکم بستر خاکریزی ترانشه را به ترتیب درست مرتب کنید.', '["ریختن خاک در لایه‌هایی با ضخامت مجاز","تراکم با غلتک یا کوبنده در رطوبت بهینه","آزمون تراکم صحرایی مثل مخروط ماسه (Sand cone)","مقایسه با درصد تراکم نسبی مشخصات و تأیید یا تکرار"]'::jsonb, 0, 'ORDER', '[0,1,2,3]'::jsonb, 'تراکم لایه‌ای انجام و سپس با آزمون صحرایی نسبت به حداکثر دانسیتهٔ پروکتور سنجیده می‌شود.', 'ASTM D1556 / D698'),
  (array['civil_supervisor','civil_engineer'], 'بتن‌ریزی پی', 2, 'مراحل اجرای بتن‌ریزی پی ایستگاه را به ترتیب درست مرتب کنید.', '["قالب‌بندی و آرماتوربندی طبق نقشه","بازرسی و تأیید پیش از بتن‌ریزی (پوشش بتن، فاصله میلگردها)","بتن‌ریزی همراه با ویبره و کنترل اسلامپ","عمل‌آوری مرطوب بتن (Curing) و حفاظت از نمونه‌ها"]'::jsonb, 0, 'ORDER', '[0,1,2,3]'::jsonb, 'تأیید آرماتور پیش از بتن‌ریزی الزامی است و عمل‌آوری برای رسیدن به مقاومت و جلوگیری از ترک ضروری.', 'ACI 318 / ACI 308'),
  (array['coating_cp_inspector','coating_supervisor'], 'معیار حفاظت کاتدیک', 3, 'کدام دو معیار حفاظت کاتدیک فولاد مدفون طبق NACE SP0169 پذیرفته است؟', '["پتانسیل منفی‌تر از ‎−۸۵۰ mV نسبت به CSE با احتساب افت IR","حداقل ۱۰۰ mV انحراف پلاریزاسیون کاتدی","پتانسیل ‎−۵۰۰ mV نسبت به CSE در حالت روشن","انحراف مثبت ۵۰ mV نسبت به پتانسیل آزاد"]'::jsonb, 0, 'MULTI', '[0,1]'::jsonb, 'معیارهای SP0169: ‎−۸۵۰ mV (با اصلاح IR) یا ۱۰۰ mV پلاریزاسیون؛ دو گزینهٔ دیگر معیار نیستند.', 'NACE SP0169 / ISO 15589-1'),
  (array['coating_cp_inspector','coating_supervisor'], 'هالیدی', 2, 'کدام دو اقدام در بازرسی هالیدی پوشش لوله پیش از دفن درست است؟', '["استفاده از ولتاژ ثابت برای تمام ضخامت‌ها","رها کردن نقاط معیوب برای تعمیر پس از دفن","تنظیم ولتاژ بازرسی متناسب با ضخامت پوشش","علامت‌گذاری و تعمیر هر نقطهٔ جرقه پیش از پایین‌گذاری"]'::jsonb, 0, 'MULTI', '[2,3]'::jsonb, 'ولتاژ هالیدی با ضخامت پوشش تنظیم می‌شود و هر عیب باید قبل از دفن اصلاح و دوباره بازرسی شود.', 'NACE SP0188 / ISO 21809-1'),
  (array['coating_cp_inspector','coating_supervisor'], 'پوشش سرجوش', 2, 'مراحل پوشش سرجوش با آستین شرینک (Heat-shrink sleeve) را به ترتیب درست مرتب کنید.', '["زدودن آلودگی و آماده‌سازی سطح تا درجهٔ مشخص‌شده","پیش‌گرم محل اتصال تا دمای توصیه‌شدهٔ سازنده","نصب آستین و حرارت‌دهی تا چسبیدن کامل","بازرسی هالیدی و آزمون چسبندگی روی نمونه"]'::jsonb, 0, 'ORDER', '[0,1,2,3]'::jsonb, 'سطح باید قبل از پیش‌گرم آماده شود و بازرسی نهایی پس از خنک شدن انجام شود.', 'ISO 21809-3 / NACE SP0108'),
  (array['coating_cp_inspector','coating_supervisor'], 'پتانسیل لوله به خاک', 2, 'مراحل اندازه‌گیری پتانسیل لوله به خاک را به ترتیب درست مرتب کنید.', '["اتصال ولت‌متر به لوله از طریق نقطهٔ تست","قرار دادن نیم‌پیل مس/سولفات مس روی خاک مرطوب بالای لوله","قرائت پتانسیل روشن (ON) با جریان برقرار","قطع هم‌زمان جریان و ثبت پتانسیل لحظه‌ای (Instant-off)"]'::jsonb, 0, 'ORDER', '[0,1,2,3]'::jsonb, 'پتانسیل Instant-off عملاً مقدار بدون افت IR را نشان می‌دهد و معیار قضاوت است.', 'NACE SP0169 / SP0207'),
  (array['mechanical_piping_inspector','mechanical_piping_supervisor'], 'شیر ایمنی', 2, 'کدام دو ویژگی دربارهٔ شیر قطع سریع (Slam-shut) در ایستگاه تقلیل فشار درست است؟', '["پس از رفع فشار خودکار دوباره باز می‌شود","در فشار بیش‌ازحد یا کمتر از حد تنظیم‌شده بسته می‌شود","وظیفهٔ تنظیم پیوستهٔ فشار خروجی را برعهده دارد","پس از عملکرد فقط با بازگردانی دستی (Reset) باز می‌شود"]'::jsonb, 0, 'MULTI', '[1,3]'::jsonb, 'Slam-shut ایمنی است نه کنترلی؛ بسته می‌شود و پس از بررسی علت باید دستی ریست شود.', 'EN 14382 / EN 12186'),
  (array['mechanical_piping_inspector','mechanical_piping_supervisor'], 'آزمون شیر', 3, 'کدام دو آزمون طبق API 598 برای پذیرش شیر در کارخانه یا انبار انجام می‌شود؟', '["آزمون سختی روی بدنهٔ شیر در محل نصب","آزمون پوسته (Shell) با ۱٫۵ برابر فشار","آزمون نشیمنگاه (Seat) با فشار مشخص","آزمون خمش روی لولهٔ ورودی شیر"]'::jsonb, 0, 'MULTI', '[1,2]'::jsonb, 'API 598 آزمون پوسته و نشیمنگاه را برای شیرها تعریف می‌کند.', 'API 598 / API 6D'),
  (array['mechanical_piping_inspector','mechanical_piping_supervisor'], 'اندازه‌گیری گاز', 3, 'کدام دو عامل مستقیماً بر دقت اندازه‌گیری با اُریفیس طبق AGA-3 اثر دارند؟', '["تیز بودن لبهٔ صفحهٔ اُریفیس","رنگ پوشش خارجی لولهٔ اندازه‌گیری","تعداد پیچ‌های فلنج روی لولهٔ ورودی","طول مستقیم لوله بالادست (Straight run)"]'::jsonb, 0, 'MULTI', '[0,3]'::jsonb, 'لبهٔ تیز و پروفیل جریان توسعه‌یافته (طول مستقیم یا یکنواخت‌کننده) پیش‌نیاز ضریب تخلیهٔ استاندارد است.', 'AGA-3 / ISO 5167-2'),
