  (array['mechanical_piping_inspector','mechanical_piping_supervisor'], 'کالیبراسیون ابزار دقیق', 2, 'مراحل کالیبراسیون ترانسمیتر فشار را به ترتیب درست مرتب کنید.', '["ایزوله کردن ترانسمیتر و تخلیهٔ فشار خط","اتصال کالیبراتور فشار مرجع","اعمال نقاط ۰ تا ۱۰۰٪ و ثبت خطای هر نقطه","تنظیم، ثبت نتیجه و صدور برچسب کالیبراسیون"]'::jsonb, 0, 'ORDER', '[0,1,2,3]'::jsonb, 'ابتدا ایزوله، سپس مرجع و ثبت خطا؛ تنظیم و گواهی آخر.', 'ISA / عرف ابزار دقیق'),
  (array['pipeline_inspector','pipeline_supervisor','site_supervisor','mechanical_piping_inspector','mechanical_piping_supervisor'], 'آزمون هیدرواستاتیک', 2, 'مراحل آزمون هیدرواستاتیک یک قطعه خط را به ترتیب درست مرتب کنید.', '["پر کردن با آب و هواگیری کامل خط","بالا بردن تدریجی فشار تا فشار آزمون","نگه‌داشتن فشار و ثبت فشار و دما در بازهٔ مشخص","تخلیهٔ کنترل‌شدهٔ فشار و آب پس از تأیید نتیجه"]'::jsonb, 0, 'ORDER', '[0,1,2,3]'::jsonb, 'هواگیری برای دقت آزمون و ایمنی ضروری است؛ ثبت هم‌زمان دما و فشار برای تفسیر افت فشار لازم است.', 'ASME B31.8'),
  (array['pipeline_inspector','pipeline_supervisor','site_supervisor'], 'عمق دفن', 2, 'کدام دو مقدار حداقل عمق پوشش خاک خط انتقال Class 1 طبق 49 CFR 192.327 است؟', '["۳۰ اینچ (حدود ۷۶۰ میلی‌متر) در خاک معمولی","۶ اینچ (حدود ۱۵۰ میلی‌متر) در خاک معمولی","۱۸ اینچ (حدود ۴۶۰ میلی‌متر) در ترانشهٔ سنگی","۱۲۰ اینچ (حدود ۳ متر) در ترانشهٔ سنگی"]'::jsonb, 0, 'MULTI', '[0,2]'::jsonb, 'Class 1: خاک معمولی ۳۰ in و سنگ ۱۸ in؛ در Class 2 تا 4 مقادیر بیشتر (۳۶ و ۲۴ in) است.', '49 CFR 192.327'),
